args.command:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { permit } from './limit.mjs';
const cases = [
  [-1, false], [0, true], [3, true], [4, false],
  ['0', false], [null, false], [NaN, false], [1.5, false],
  [undefined, false], [Infinity, false], [-Infinity, false]
];
for (const [input, expected] of cases) {
  assert.equal(permit(input), expected, `permit(${String(input)})`);
}
console.log('boundary/malformed assertions passed');
EOF
